import {SOILS} from './model.js';
export function plantArt(type, health=90) {
  const green=health<30?'#9b8652':health<60?'#8b9256':'#537749',light=health<30?'#b4a26a':'#91ae69';
  if(type==='moss')return `<g fill="${green}"><ellipse cx="0" cy="-9" rx="48" ry="14" fill="#617e45"/>${[-35,-22,-8,7,20,34].map((x,i)=>`<path d="M${x-11} -9Q${x-17} ${-34-i%3*8} ${x} ${-24-i%2*8}Q${x+17} -35 ${x+15} -10Z" fill="${i%2?green:light}"/><path d="M${x} -9v-13m0 8-5-5m5 2 5-5" fill="none" stroke="#45673b" stroke-width="1.2"/>`).join('')}</g>`;
  if(type==='fern')return `<g stroke="#49633b" stroke-width="1.5" fill="${green}">${[-55,-28,0,28,55].map((a,k)=>`<g transform="rotate(${a})"><path d="M0 0Q-9 -60 0 ${-108+k%2*20}" fill="none"/>${Array.from({length:7},(_,i)=>{let y=-20-i*12,w=23-i*2;return `<path d="M-3 ${y}Q${-w-9} ${y+4} ${-w} ${y-14}Q-7 ${y-10} -3 ${y}Z" fill="${i%2?light:green}"/><path d="M-3 ${y-3}Q${w+5} ${y} ${w} ${y-19}Q2 ${y-12} -3 ${y-3}Z"/>`}).join('')}</g>`).join('')}</g>`;
  return `<g stroke="#536c3f" stroke-width="2">${[-30,0,35].map((a,k)=>`<g transform="rotate(${a})"><path d="M0 0Q8 -50 0 ${-97+k*8}" fill="none"/>${[0,1,2].map((i)=>`<path d="M3 ${-23-i*25}C-44 ${-12-i*25} -37 ${-58-i*25} -25 ${-52-i*25}Q-4 ${-48-i*25} 3 ${-23-i*25}" fill="${green}"/><path d="M4 ${-32-i*25}C43 ${-14-i*25} 39 ${-53-i*25} 29 ${-57-i*25}Q13 ${-51-i*25} 4 ${-32-i*25}" fill="${light}"/>`).join('')}</g>`).join('')}</g>`;
}
export function icon(type) {return `<svg class="choice-icon" viewBox="0 0 70 65" aria-hidden="true">${SOILS[type]?`<ellipse cx="35" cy="47" rx="28" ry="11" fill="#ddd6bf"/><path d="M9 42 22 30 35 27 52 34 61 43Q35 60 9 42" fill="${SOILS[type].color}"/>${Array.from({length:13},(_,i)=>`<circle cx="${18+(i*13)%36}" cy="${35+(i*7)%13}" r="1.5" fill="#cfb38a"/>`).join('')}`:type==='springtails'?'<g fill="#a39776" stroke="#7e745b"><ellipse cx="32" cy="34" rx="14" ry="8"/><circle cx="47" cy="30" r="6"/><path d="m23 37-6 8m15-8-3 10m12-11 7 9m-1-19 5-9m-2 10 10-2"/></g>':type==='woodlice'?'<g stroke="#716b5b" stroke-width="2"><ellipse cx="35" cy="35" rx="20" ry="13" fill="#9b9580"/><path d="M24 24v22m7-24v26m8-25v25m8-20v15M21 43l-4 5m12-2-1 5m12-5 2 5m10-12 5 3m-5-12 8-3" fill="none"/></g>':`<g transform="translate(35 58) scale(.43)">${plantArt(type)}</g>`}</svg>`}
export function sceneArt(s,fx='') {
 const soilColor=SOILS[s.soil]?.color||'#92734f';
 const soil=s.soil?`<g class="${fx==='soil'?'pour-soil':''}"><path d="M130 303Q280 275 430 303L430 348Q280 389 130 348Z" fill="${soilColor}"/><path d="M130 319Q280 301 430 319V350Q280 389 130 350Z" fill="#251f18" opacity="${s.moisture/200}"/><ellipse cx="280" cy="303" rx="150" ry="29" fill="${soilColor}"/><ellipse cx="280" cy="303" rx="150" ry="29" fill="#251f18" opacity="${s.moisture/230}"/>${Array.from({length:60},(_,i)=>`<ellipse cx="${140+i*47%280}" cy="${302+i*13%52}" rx="${1+i%3}" ry="1.4" fill="${i%3?'#bea782':'#443628'}" opacity=".5"/>`).join('')}</g>`:'';
 const plants=s.plants.map((p,i)=>p?`<g transform="translate(${[202,280,358][i]} ${[302,312,300][i]}) scale(${p.growth*.87})"><g transform="rotate(${p.health<45?(i%2?15:-18):0})"><g class="sprig plant-art" style="animation-delay:-${i*2}s">${plantArt(p.species,p.health)}</g></g></g>`:'').join('');
 const creatures=s.creatures.map((c,k)=>Array.from({length:c==='springtails'?4:2},(_,i)=>`<g transform="translate(${185+i*49+k*25} ${315+k*6})" opacity="${.35+s.creatureHealth/155}"><g class="creature-motion" style="animation-duration:${s.creatureHealth<35?45:15+i*3}s;animation-delay:-${i*4}s">${c==='springtails'?'<ellipse rx="3.5" ry="1.8" fill="#dbd5b9"/><circle cx="4" cy="-1" r="1.8" fill="#e5dfc9"/>':'<ellipse rx="7" ry="4" fill="#7e7b68" stroke="#4c4e3e" stroke-width=".8"/><path d="M-3-3v6M0-4v8M3-3v6" stroke="#b8b59a" stroke-width=".7"/>'}</g></g>`).join('')).join('');
 const drops=Array.from({length:22},(_,i)=>`<path d="M${140+i*53%280} ${145+i*31%145}q-5 8 0 9q5-1 0-9" fill="#eaf6ef" stroke="#a9c6b1" stroke-width=".5" opacity="${s.soil?Math.max(0,(s.moisture-42)/85)*(i%3===0?1:.6):0}" class="glass-droplet"/>`).join('');
 return `<svg viewBox="0 0 560 430" role="img" aria-labelledby="terrarium-title"><title id="terrarium-title">Glass terrarium with ${s.soil?SOILS[s.soil].name:'no soil'}, ${s.plants.filter(Boolean).length} plants. Moisture ${Math.round(s.moisture)} percent, light ${s.light} percent.</title><defs><linearGradient id="glass" x1="0" x2="1"><stop stop-color="#e1eee2" stop-opacity=".38"/><stop offset=".4" stop-color="#ffffff" stop-opacity=".13"/><stop offset="1" stop-color="#c9ded1" stop-opacity=".45"/></linearGradient><linearGradient id="shine" x1="0" x2="1"><stop stop-color="white" stop-opacity=".65"/><stop offset="1" stop-color="white" stop-opacity="0"/></linearGradient><clipPath id="jar-clip"><path d="M204 72V102C204 136 121 164 119 243V327Q119 377 280 380Q441 377 441 327V243C439 164 356 136 356 102V72Z"/></clipPath><radialGradient id="halo"><stop stop-color="#ffffd9" stop-opacity=".8"/><stop offset="1" stop-color="#ffffe0" stop-opacity="0"/></radialGradient></defs>
 <ellipse cx="280" cy="377" rx="179" ry="19" fill="#8f9d76" opacity=".13"/><ellipse cx="280" cy="381" rx="127" ry="9" fill="#7d8b67" opacity=".1"/>
 <g opacity=".35" stroke="#9aaa7c" fill="none" stroke-width="1"><path d="M76 346Q86 290 61 250m18 55q-35 1-30-31 22 3 30 31m-4-15q27-12 16-33-20 9-16 33M470 349q-11-61 20-98m-17 69q-22-11-17-30 18 5 17 30m1-24q34-6 27-30-25 8-27 30"/></g>
 <ellipse cx="300" cy="196" rx="202" ry="172" fill="url(#halo)" opacity="${s.light/100}" class="light-wash"/>
 <path d="M204 72V102C204 136 121 164 119 243V327Q119 377 280 380Q441 377 441 327V243C439 164 356 136 356 102V72Z" fill="url(#glass)" stroke="#a6bdad" stroke-width="2"/>
 <g clip-path="url(#jar-clip)"><path d="M128 348Q280 390 433 348v27H128Z" fill="#c4b99b" opacity=".7"/>${soil}${plants}${creatures}<rect x="118" y="80" width="324" height="300" fill="#2f4038" opacity="${(100-s.light)*.0013}" class="light-wash"/>${drops}${fx==='water'?`<g class="rain" stroke="#9abeb5" stroke-width="2" stroke-linecap="round">${Array.from({length:19},(_,i)=>`<path d="M${180+i*31%202} ${125+i*13%90}v11"/>`).join('')}</g>`:''}</g>
 <path d="M190 141Q141 190 141 250V304" stroke="url(#shine)" stroke-width="13" stroke-linecap="round" fill="none"/><path d="M406 216q12 25 11 67" stroke="#fff" stroke-opacity=".5" stroke-width="5" stroke-linecap="round" fill="none"/>
 <ellipse cx="280" cy="72" rx="78" ry="15" fill="#d6e3d4" fill-opacity=".6" stroke="#9bb29d" stroke-width="2"/><ellipse cx="280" cy="72" rx="69" ry="10" fill="#c7d5c3" fill-opacity=".4" stroke="#afc1a8"/>
 <path d="M197 66v-12q83-22 166 0v12q-83 19-166 0" fill="#b7a27a" stroke="#938164"/><ellipse cx="280" cy="53" rx="83" ry="12" fill="#cabc99" stroke="#aa9874"/>${Array.from({length:23},(_,i)=>`<path d="m${211+i*19%139} ${51+i*3%14}h${1+i%3}" stroke="#9b8b67" stroke-width="1" opacity=".6"/>`).join('')}
 ${!s.soil?'<text x="280" y="238" text-anchor="middle" fill="#839373" font-family="Georgia,serif" font-size="14" font-style="italic">A little possibility.</text>':''}</svg>`;
}
